"""Exact evaluation of the Berggren node-counting function N(H) via the seed bijection."""

from __future__ import annotations

from math import gcd, isqrt
from typing import Iterator, List, Tuple

Seed = Tuple[int, int]


def admissible_seeds_below(H: int) -> Iterator[Seed]:
    """Yield every admissible Euclid seed (m, n) with m^2 + n^2 <= H.

    A seed is admissible when n < m, n >= 1, gcd(m, n) = 1 and m + n is odd.
    By the seed bijection these are in one-to-one correspondence with the nodes
    of the Berggren tree, the node's hypotenuse being c = m^2 + n^2.
    """
    for m in range(2, isqrt(H) + 1):
        for n in range(1, m):
            if m * m + n * n > H:
                break                       # inner loop is monotone in n
            if gcd(m, n) == 1 and (m + n) % 2 == 1:
                yield (m, n)


def count_nodes_below(H: int) -> int:
    """N(H) = #{ nodes w of the Berggren tree : c(w) <= H }, computed exactly."""
    return sum(1 for _ in admissible_seeds_below(H))


def counting_bounds(H: int) -> Tuple[float, int, int]:
    """Return (proved lower bound, exact N(H), proved upper bound)."""
    from math import log, sqrt

    eps_sq = 3.0 + 2.0 * sqrt(2.0)
    sigma0 = log(3.0) / log(eps_sq)          # = log 3 / (2 log(1+sqrt 2))
    lower = (1.0 / 3.0) * (H / 5.0) ** sigma0 if H >= 5 else 0.0
    upper = (isqrt(H) + 1) ** 2
    return (lower, count_nodes_below(H), upper)


def partial_tree_zeta(s: float, H: int) -> float:
    """Partial sum of the tree zeta sum_w c(w)^{-s} over all nodes with c(w) <= H."""
    return sum((m * m + n * n) ** (-s) for m, n in admissible_seeds_below(H))


if __name__ == "__main__":
    print(f"{'H':>9} {'lower':>12} {'N(H)':>9} {'upper':>10} {'N(H)/H':>9}")
    for H in (5, 50, 200, 1000, 10 ** 4, 10 ** 5, 10 ** 6):
        lo, N, up = counting_bounds(H)
        print(f"{H:9d} {lo:12.2f} {N:9d} {up:10d} {N / H:9.5f}")
